/bin/bash -lc "python -u - <<'PY'
import assemblyai as a, httpx
models=a.LLMGateway().models.list().data
for m in models:
 print(m.id,'retirement:',m.retirement_date)
original=httpx.Client.send
def send(self,request,*args,**kwargs):
 response=original(self,request,*args,**kwargs)
 if response.status_code>=400: print('Error detail:',response.text)
 return response
httpx.Client.send=send
for model in ['claude-haiku-5-5','claude-sonnet-5-5','gpt-6-luna','gemini-3.8-flash']:
 try:
  response=a.LLMGateway().chat.completions.create(model=model,max_tokens=128,messages=[{'role':'user','content':'Summarize in two sentences: Quorvex ships Thursday. Talvanta moves to the next sprint.'}])
  print('Success:',model,response.choices)
  break
 except Exception as e: print('Failed:',model,str(e))
PY"

